import React, { useState, useEffect, useMemo } from 'react';
import axios from 'axios';
import PostForm from './components/PostForm';
import PostList from './components/PostList';
import { getTimeGreeting } from './utils/humanize';
import './App.css';

const API_BASE_URL = '/api/posts';

function App() {
  const [posts, setPosts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [editingPost, setEditingPost] = useState(null);
  const [toast, setToast] = useState(null);
  const [postToDelete, setPostToDelete] = useState(null);

  const showToast = (message, type = 'success') => {
    setToast({ message, type, id: Date.now() });
    setTimeout(() => {
      setToast(null);
    }, 4000);
  };

  const fetchPosts = async () => {
    try {
      setLoading(true);
      const response = await axios.get(API_BASE_URL);
      setPosts(response.data);
      setError(null);
    } catch (err) {
      setError('Unable to reach the blog service. Please ensure the backend server is running.');
      console.error('Error fetching posts:', err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchPosts();
  }, []);

  const handleCreatePost = async (postData) => {
    try {
      const response = await axios.post(API_BASE_URL, postData);
      setPosts(prev => [response.data, ...prev]);
      showToast('🎉 Your story was published successfully!');
    } catch (err) {
      const msg = err.response?.data?.message || 'We could not publish your post right now.';
      showToast(`⚠️ ${msg}`, 'error');
      throw new Error(msg);
    }
  };

  const handleUpdatePost = async (id, postData) => {
    try {
      const response = await axios.put(`${API_BASE_URL}/${id}`, postData);
      setPosts(prev => prev.map(post => post._id === id ? response.data : post));
      setEditingPost(null);
      showToast('✨ Story updated seamlessly!');
    } catch (err) {
      const msg = err.response?.data?.message || 'We could not update your post right now.';
      showToast(`⚠️ ${msg}`, 'error');
      throw new Error(msg);
    }
  };

  const requestDeletePost = (id) => {
    const target = posts.find(p => p._id === id);
    setPostToDelete(target || { _id: id, title: 'this story' });
  };

  const confirmDeletePost = async () => {
    if (!postToDelete) return;
    const id = postToDelete._id;
    setPostToDelete(null);

    try {
      await axios.delete(`${API_BASE_URL}/${id}`);
      setPosts(prev => prev.filter(post => post._id !== id));
      showToast('🗑️ Story deleted cleanly.');
    } catch (err) {
      const msg = err.response?.data?.message || 'Failed to delete post.';
      showToast(`⚠️ ${msg}`, 'error');
    }
  };

  const handleEditPost = (post) => {
    setEditingPost(post);
    // Smooth scroll to top of the sidebar form if on smaller screen
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleCancelEdit = () => {
    setEditingPost(null);
  };

  const greeting = getTimeGreeting();

  const totalWords = useMemo(() => {
    return posts.reduce((acc, p) => {
      const words = (p.content || '').trim().split(/\s+/).filter(Boolean).length;
      return acc + words;
    }, 0);
  }, [posts]);

  const totalReadingMinutes = Math.max(1, Math.ceil(totalWords / 200));

  const uniqueAuthors = useMemo(() => {
    const set = new Set(posts.map(p => (p.author || '').trim().toLowerCase()).filter(Boolean));
    return set.size;
  }, [posts]);

  return (
    <div className="app">
      {/* Toast Notification */}
      {toast && (
        <div className={`toast-notification toast-${toast.type} slide-in`} role="status">
          <span>{toast.message}</span>
          <button 
            type="button" 
            className="toast-close" 
            onClick={() => setToast(null)}
            aria-label="Dismiss notification"
          >
            ×
          </button>
        </div>
      )}

      {/* Delete Confirmation Modal */}
      {postToDelete && (
        <div className="modal-overlay fade-in" role="dialog" aria-modal="true" aria-labelledby="modal-title">
          <div className="modal-card slide-in">
            <div className="modal-icon-wrap">
              <span className="modal-icon">🗑️</span>
            </div>
            <h3 id="modal-title" className="modal-title">Delete Story?</h3>
            <p className="modal-text">
              Are you sure you want to delete <strong>"{postToDelete.title}"</strong>? This action cannot be reversed.
            </p>
            <div className="modal-actions">
              <button 
                type="button" 
                className="btn btn-secondary" 
                onClick={() => setPostToDelete(null)}
              >
                Keep Story
              </button>
              <button 
                type="button" 
                className="btn btn-danger" 
                onClick={confirmDeletePost}
              >
                Yes, Delete
              </button>
            </div>
          </div>
        </div>
      )}

      <header className="app-header">
        <div className="header-content">
          <div className="header-badge">
            <span>✨ {greeting}, Storyteller</span>
          </div>
          <h1 className="app-title">OpenCode Stories</h1>
          <p className="app-subtitle">A thoughtful space to read, write, and exchange inspiring thoughts</p>

          <div className="stats-row">
            <div className="stat-pill">
              <span className="stat-icon">📖</span>
              <span className="stat-val">{posts.length}</span>
              <span className="stat-lbl">{posts.length === 1 ? 'Story' : 'Stories'}</span>
            </div>
            <div className="stat-pill">
              <span className="stat-icon">✍️</span>
              <span className="stat-val">{uniqueAuthors}</span>
              <span className="stat-lbl">{uniqueAuthors === 1 ? 'Author' : 'Authors'}</span>
            </div>
            <div className="stat-pill">
              <span className="stat-icon">☕</span>
              <span className="stat-val">{totalReadingMinutes}m</span>
              <span className="stat-lbl">Read Time</span>
            </div>
          </div>
        </div>
      </header>

      <main className="app-main">
        <div className="container">
          {error && (
            <div className="alert alert-error" role="alert">
              <svg className="alert-icon" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
              </svg>
              <span>{error}</span>
              <button className="alert-dismiss" onClick={() => setError(null)} aria-label="Dismiss error">
                <svg fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                </svg>
              </button>
            </div>
          )}

          <div className="content-layout">
            <aside className="layout-sidebar">
              <PostForm
                onSubmit={handleCreatePost}
                onUpdate={handleUpdatePost}
                editingPost={editingPost}
                onCancelEdit={handleCancelEdit}
                loading={loading}
              />
            </aside>

            <section className="layout-main">
              <PostList
                posts={posts}
                loading={loading}
                onEdit={handleEditPost}
                onDelete={requestDeletePost}
              />
            </section>
          </div>
        </div>
      </main>

      <footer className="app-footer">
        <p>Crafted with care using React, Node.js, Express & MongoDB 💖</p>
      </footer>
    </div>
  );
}

export default App;
